    非 bool 非负 int；atomic 为 bool。类型阶段先查容器/各 sid/now_ms/
    atomic 的类型；取值阶段依序查 sid 取值与 now_ms 下界、长度上下界、
    sid 重复。
    """
    # 类型阶段：任一类型错先于任何取值错抛出。
    if not isinstance(sids, tuple):
        raise TypeError(f"sids must be a tuple, got {type(sids).__name__}")
